using System;
using System.Linq;
using UnityEngine;
namespace IanGame {
// Persistent life data. Time, money, stats, employment and missions remain owned by the original systems.
public sealed partial class LifeWorldService:MonoBehaviour {
 public CityLifeService City{get;private set;}
 public LifeWorldRules rules;LifeWorldRules legacyRules;public RoomSceneCatalog rooms;public LifeWorldController Host{get;private set;}public GameManager Game{get;private set;}
 public LifeWorldSnapshot State{get;private set;}=new LifeWorldSnapshot();public bool Executing{get;private set;}
 public bool Active=>Host!=null;public bool Busy=>Host!=null&&Host.Busy;public int Hour=>Game==null?8:(int)(Game.clock.SubDaySeconds/3600);
 public SceneId Location=>rules?.Zone(State.zone)?.location??SceneId.Home;public event Action Restored,Changed;
 public void Configure(GameManager game){legacyRules=rules;Game=game;if(rooms?.rules!=null&&GameContext.Instance!=null&&GameContext.Instance.transitions.IsRoomArchitecture)rules=rooms.rules;game.clock.SimulationAdvanced+=Tick;game.clock.DayChanged+=Day;City=new CityLifeService(this);}
 void OnDestroy(){City?.Dispose();if(Game!=null){Game.clock.SimulationAdvanced-=Tick;Game.clock.DayChanged-=Day;}}
 public void Attach(LifeWorldController host){var identity=host.GetComponent<RoomSceneIdentity>();if(identity!=null)UseRoomRules(identity.catalog);else UseLegacyRules();Host=host;Game.clock.realSecondsPerGameDay=rules.realSecondsPerGameDay;Game.clock.realtimeEnabled=Game.realtimeLifeEnabled;if(Game.idle.State.active){Game.idle.StopActivity();Game.Log("자동 활동을 중지하고 직접 생활을 이어갑니다.");}}
 public void Detach(LifeWorldController host){if(Host==host)Host=null;}
 void Tick(double seconds){if(RoomMode)AdvanceAbsentResidents();if(!Active)return;State.fatigue=Mathf.Clamp(State.fatigue+(float)(seconds/86400*rules.fatiguePerDay),0,100);State.hygiene=Mathf.Clamp(State.hygiene-(float)(seconds/86400*rules.hygieneLossPerDay),0,100);}
 void Day(int day){if(!Active||day<=State.lastSummaryDay)return;State.lastSummary=$"DAY {day-1} 생활 기록 · 수입 {State.dailyIncome:N0}G\n피로 {State.fatigue:0} / 위생 {State.hygiene:0} · 오늘도 삶은 계속됩니다.";State.dailyIncome=0;State.lastSummaryDay=day;Changed?.Invoke();}
 public void ResetLife(){State=new LifeWorldSnapshot{zone=FamilyLife.Home,position=new Vector2(-5,-.7f),family=new FamilyLifeSnapshot{schema=1}};if(RoomMode)rooms.Migrate(State,0);Restored?.Invoke();}
 public LifeWorldSnapshot Capture(){if(Host!=null&&(Host.Room==null||Host.Room.roomId==State.zone)){Host.CapturePosition();Host.GetComponent<WorldNPCScheduler>()?.Capture();}return JsonUtility.FromJson<LifeWorldSnapshot>(JsonUtility.ToJson(State));}
 public void Restore(LifeWorldSnapshot value){State=value==null||value.schema==0?new LifeWorldSnapshot():JsonUtility.FromJson<LifeWorldSnapshot>(JsonUtility.ToJson(value));FamilyLife.Migrate(Game,State);if(!RoomMode&&State.zone==FamilyLife.Bath){State.zone=FamilyLife.Home;State.position=new Vector2(8,2.3f);}if(RoomMode)rooms.Migrate(State,Game.growth.Age);if(State.residents==null)State.residents=new System.Collections.Generic.List<NPCResidentSnapshot>();bool interrupted=!string.IsNullOrEmpty(State.pendingAction);State.pendingAction="";if(rules!=null&&rules.Zone(State.zone)==null){State.zone="home";State.position=rules.Zone("home").spawn;}if(rules!=null&&!GrowthAccess.Zone(Game,State.zone,out _)){State.zone=RoomMode?(rooms.Resolve(FamilyLife.DefaultHome(Game),Vector2.zero,Game.growth.Age)?.roomId??"home"):FamilyLife.DefaultHome(Game);State.position=rules.Zone(State.zone).spawn;State.lastSummary="성장 단계에 맞는 집으로 돌아왔습니다. 보유 자산과 진행 기록은 유지됩니다.";}if(interrupted)State.lastSummary="진행 중이던 행동을 취소했습니다. 시간·물품·보상은 중복 처리하지 않습니다.";Restored?.Invoke();}
 public static bool Valid(LifeWorldSnapshot s)=>s==null||s.schema==0||s.schema==1&&CityLifeService.Valid(s.cityLife)&&!string.IsNullOrEmpty(s.zone)&&float.IsFinite(s.position.x)&&float.IsFinite(s.position.y)&&Math.Abs(s.position.x)<100&&Math.Abs(s.position.y)<100&&float.IsFinite(s.facing.x)&&float.IsFinite(s.facing.y)&&s.fatigue>=0&&s.fatigue<=100&&s.hygiene>=0&&s.hygiene<=100&&s.rice>=0&&s.rice<=999&&s.bread>=0&&s.bread<=999&&(s.prepared==""||s.prepared=="rice"||s.prepared=="bread")&&s.lastWorkDay>=-1&&s.dailyIncome>=0&&FamilyLife.Valid(s.family)&&ValidResidents(s.residents);
 public static bool ValidResidents(System.Collections.Generic.List<NPCResidentSnapshot> list)=>list==null||list.Count<=128&&list.All(n=>n!=null&&!string.IsNullOrEmpty(n.id)&&!string.IsNullOrEmpty(n.zone)&&float.IsFinite(n.position.x)&&float.IsFinite(n.position.y)&&Math.Abs(n.position.x)<100&&Math.Abs(n.position.y)<100&&float.IsFinite(n.facing.x)&&float.IsFinite(n.facing.y)&&Enum.IsDefined(typeof(NPCDailyAction),n.action)&&n.minute>=0)&&list.Select(n=>n.id).Distinct().Count()==list.Count;
 public static string ZoneFor(SceneId scene)=>scene==SceneId.Home?"home":scene==SceneId.City?"city":scene==SceneId.Workplace?"workplace":scene==SceneId.School?"school":scene==SceneId.Shop?"shop":null;
 public void SelectDestination(SceneId scene){string id=ZoneFor(scene);if(id==null||rules==null||!GrowthAccess.Zone(Game,id,out _))return;if(id=="home")id=FamilyLife.DefaultHome(Game);State.zone=id;State.position=rules.Zone(id).spawn;}
 public bool CanAction(int action,out string reason){reason=null;if(!Active)return true;if(Busy&&!Executing){reason="행동을 마치거나 취소하세요.";return false;}if(action==0){if(State.lastWorkDay==Game.clock.Day||Game.phase23.Progress.employment.work.Exists(w=>w.day==Game.clock.Day&&w.paid)){reason="오늘 근무를 이미 마쳤습니다.";return false;}if(Hour<rules.workOpen||Hour>rules.workLastStart){reason=$"출근 시간은 {rules.workOpen:00}:00–{rules.workLastStart:00}:59입니다. 늦으면 다음 날 출근하세요.";return false;}if(State.fatigue>90){reason="피로가 높습니다. 먼저 충분히 쉬세요.";return false;}}return true;}
 public double Duration(int action){if(action==0)return rules.shiftHours*3600;if(action==5)return 8*3600;if(action==3)return 30*60;if(action==4)return 2*60;if(action==1||action==2)return 60*60;if(action==6)return 60*60;if(action==18||action==9||action==19)return 20*60;return 60*60;}
 public bool CommitAction(int action){Executing=true;try{int day=Game.clock.Day;long cash=Game.economy.Cash;bool ok=Game.TryTimedAction(action,Duration(action));if(ok){if(action==5)State.fatigue=Mathf.Max(0,State.fatigue-80);if(action==1)State.fatigue=Mathf.Max(0,State.fatigue-20);if(action==0){State.lastWorkDay=day;State.fatigue=Mathf.Min(100,State.fatigue+12);State.dailyIncome+=Math.Max(0,Game.economy.Cash-cash);}if((action==18||action==9||action==19)&&State.hygiene<20)Game.stats.ApplyCore(new StatDelta{social=-1});}return ok;}finally{Executing=false;}}
 public bool Durable(Func<bool> mutation,out string message){var before=Game.CaptureState();bool auto=Game.autoSaveAfterAction;Game.autoSaveAfterAction=false;try{if(!mutation()){Game.RestoreState(before);message="조건을 충족하지 못해 변경하지 않았습니다.";return false;}if(!Game.SaveAutomaticCheckpoint(out message)){Game.RestoreState(before);message="저장 실패 · 변경을 취소했습니다.";return false;}Changed?.Invoke();return true;}catch(Exception e){Game.RestoreState(before);Debug.LogWarning(e);message="처리 중단 · 상태를 보존했습니다. 다시 시도하세요.";return false;}finally{Game.autoSaveAfterAction=auto;}}
 public bool PurchaseFood(string id,out string message){if(!GrowthAccess.Independent(Game)||!Active||Busy||Game.State!=GameState.Playing||State.zone!="shop"||!Host.NearbyKind(WorldInteractionKind.FoodShop)||Hour<rules.shopOpen||Hour>=rules.shopClose){message="영업 중인 상점의 계산대에서 구매하세요.";return false;}int price=id=="rice"?rules.ricePrice:rules.breadPrice;return Durable(()=>{if(id!="rice"&&id!="bread"||id=="rice"&&State.rice>=999||id=="bread"&&State.bread>=999||!Game.economy.TrySpend(price,id=="rice"?"식료품 · 쌀":"식료품 · 빵"))return false;if(id=="rice")State.rice++;else State.bread++;City?.Record("purchase");return true;},out message);}
}
}
